std::vector<Tetrahedron> result;
for (auto it = tri.finite_cells_begin(); it != tri.finite_cells_end(); ++it) {
    Tetrahedron tet;
    int index = 0;
    for (auto vertex : it->vertices()) {
        tet[index++] = vertex->point();
    }
    result.push_back(tet);
}
return result;

